async def test_vector_52_turnconformance_run_bindings_injected():
    vector_json = r"""
    {
      "name": "bindings_injected",
      "description": "Tool has a binding {unit: {input: 'preferred_unit'}}. The LLM omits the bound parameter. At execution time, the binding injects the value from the parent inputs, so the tool receives the merged arguments.",
      "stage": "agent",
      "input": {
        "messages": [
          {
            "role": "system",
            "content": "You are a helpful weather assistant."
          },
          {
            "role": "user",
            "content": "What is the weather in Paris?"
          }
        ],
        "parent_inputs": {
          "preferred_unit": "celsius"
        },
        "tools": [
          {
            "name": "get_weather",
            "kind": "function",
            "description": "Get the current weather for a city",
            "parameters": [
              {
                "name": "city",
                "kind": "string",
                "required": true
              },
              {
                "name": "unit",
                "kind": "string",
                "required": false
              }
            ],
            "bindings": {
              "unit": {
                "input": "preferred_unit"
              }
            }
          }
        ],
        "tool_functions": {
          "get_weather": "returns weather string"
        }
      },
      "sequence": [
        {
          "turn": 1,
          "llm_response": {
            "id": "chatcmpl-binding-001",
            "object": "chat.completion",
            "choices": [
              {
                "index": 0,
                "message": {
                  "role": "assistant",
                  "content": null,
                  "tool_calls": [
                    {
                      "id": "call_bind_001",
                      "type": "function",
                      "function": {
                        "name": "get_weather",
                        "arguments": "{\"city\": \"Paris\"}"
                      }
                    }
                  ]
                },
                "finish_reason": "tool_calls"
              }
            ]
          },
          "expected_tool_calls": [
            {
              "id": "call_bind_001",
              "name": "get_weather",
              "arguments": {
                "city": "Paris"
              }
            }
          ],
          "expected_execution_args": {
            "get_weather": {
              "city": "Paris",
              "unit": "celsius"
            }
          },
          "tool_results": [
            {
              "tool_call_id": "call_bind_001",
              "result": "22°C sunny"
            }
          ]
        },
        {
          "turn": 2,
          "llm_response": {
            "id": "chatcmpl-binding-002",
            "object": "chat.completion",
            "choices": [
              {
                "index": 0,
                "message": {
                  "role": "assistant",
                  "content": "The weather in Paris is 22°C and sunny.",
                  "tool_calls": null
                },
                "finish_reason": "stop"
              }
            ]
          },
          "expected_tool_calls": null
        }
      ],
      "expected": {
        "result": "The weather in Paris is 22°C and sunny.",
        "iterations": 2,
        "total_messages": 6,
        "notes": "The binding {unit: {input: 'preferred_unit'}} resolves 'preferred_unit' from parent_inputs to 'celsius' and injects it into the tool call arguments before execution, overriding any LLM-provided value."
      },
      "operation": "run"
    }
    """
    vector = json.loads(vector_json, strict=False)
    await run_vector("TurnConformance", "run", vector, False, _SEAM)


